<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,date,errorText} from '../api';import {useAuth} from '../stores/auth';import PageHeading from '../components/PageHeading.vue';import Modal from '../components/Modal.vue';import {isDemo} from '../demo';
import {Plus,Download,FileText} from 'lucide-vue-next';
const auth=useAuth(),reports=ref<any[]>([]),works=ref<any[]>([]),error=ref(''),busy=ref(false),show=ref(false),file=ref<File|null>(null),form=ref({title:'Informe mensual',work_item_id:''});async function load(){try{reports.value=(await api.get('/reports')).data;}catch(e){error.value=errorText(e);}}async function create(){if(!file.value)return;busy.value=true;try{const fd=new FormData();fd.append('title',form.value.title);fd.append('work_item_id',String(form.value.work_item_id));fd.append('file',file.value);await api.post('/reports',fd);show.value=false;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}function useSample(){file.value=new File(['%PDF-1.4\nInforme ficticio de demostración.'],'informe-de-ejemplo.pdf',{type:'application/pdf'});}
async function publish(r:any){busy.value=true;try{await api.post(`/reports/${r.id}/publish`);await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}onMounted(async()=>{await load();if(auth.staff)try{works.value=(await api.get('/works')).data.filter((w:any)=>!['delivered','cancelled'].includes(w.status));}catch(e){error.value=errorText(e);}});
</script>
<template><PageHeading title="Informes y entregas" :subtitle="auth.staff?'Prepara, aprueba y publica cada entrega.':'Los informes que tu estudio ha publicado para tus empresas.'"><button v-if="auth.staff" class="button primary" @click="show=true"><Plus :size="16"/>Nuevo informe</button></PageHeading><p v-if="error" class="error" role="alert">{{error}}</p><section class="panel"><div class="document-row" v-for="r in reports" :key="r.id"><span class="file-icon"><FileText :size="22"/></span><div class="document-description"><strong>{{r.title}}</strong><small>{{r.company.name}} · {{r.work?.period}}</small><small v-if="r.published_at">Publicado el {{date(r.published_at)}}</small></div><span class="badge" :class="r.published_at?'accepted':'pending'">{{r.published_at?'Publicado':'Borrador'}}</span><div class="actions"><a v-if="r.files[0]" :href="`/api/files/${r.files[0].id}`" class="button"><Download :size="15"/>Descargar</a><button v-if="auth.reviewer&&!r.published_at" class="button primary" :disabled="busy" @click="publish(r)">Aprobar y publicar</button></div></div><p v-if="!reports.length" class="empty">{{auth.staff?'Todavía no hay informes. Crea la primera entrega.':'Todavía no tienes informes publicados.'}}</p><div class="panel-note">{{isDemo?'Las descargas generan un documento ficticio, sin valor contable.':'La descarga queda registrada y no implica conformidad con el contenido.'}}</div></section><Modal v-if="show" title="Nuevo informe" @close="show=false"><form @submit.prevent="create" class="stack-form"><label>Trabajo<select aria-label="Trabajo" v-model="form.work_item_id" required><option value="" disabled>Selecciona un trabajo</option><option v-for="w in works" :key="w.id" :value="w.id">{{w.company.name}} · {{w.title}} · {{w.period}}</option></select></label><label>Título<input v-model="form.title" required maxlength="180"></label><div v-if="isDemo"><button class="button" type="button" @click="useSample">Usar informe de ejemplo</button><small v-if="file">Seleccionado: {{file.name}}</small><p class="demo-file-note">Se simula el archivo; no se guarda su contenido.</p></div><label>Archivo PDF (máximo 10 MB)<input type="file" accept=".pdf" :required="!file" @change="file=($event.target as HTMLInputElement).files?.[0]||null"></label><p class="footnote">Para una nueva versión, crea otro informe en el mismo trabajo. Las entregas anteriores se conservan.</p><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="busy">Guardar borrador</button></form></Modal></template>
